                    992: { items: 2 },    // Desktop → Show 2 news
                }
            });

            $('.news-next-btn').click(function () {
                newsSlider.trigger('next.owl.carousel');
            });

        });

    </script>


    <script>
        let index = 0;
        const managers = document.querySelectorAll('.management-item');

        function showNextManager() {
            managers[index].classList.remove('active');
            index = (index + 1) % managers.length;
            managers[index].classList.add('active');
        }

        setInterval(showNextManager, 4000); // smoother, slower
    </script>

    <script>
        document.addEventListener("DOMContentLoaded", function () {

            const toppers = @json($toppers);
            const container = document.getElementById("toppersContainer");

            let currentIndex = 0;
            const visibleCount = 4;

            function topperCard(item) {
                return `
                                                                                            <div class="topper-card">
                                                                                                <span class="topper-class">Class: ${item.class?.title ?? 'N/A'}</span>
                                                                                                <img src="${item.image_url}" class="topper-photo">
                                                                                                <h5 class="topper-name">${item.name}</h5>
                                                                                                <div class="topper-marks">${item.marks}%</div>
                                                                                                <a href="{{ route('all-toppers') }}"
                                                                                                   style="
                                                                                                        display:inline-block;
                                                                                                        margin-top:12px;
                                                                                                        padding:6px 16px;
                                                                                                        background:#f8c62f;
                                                                                                        color:#000;
                                                                                                        border-radius:20px;
                                                                                                        font-size:13px;
                                                                                                        font-weight:600;
                                                                                                        text-decoration:none;
                                                                                                   ">
                                                                                                   View
                                                                                                </a>
                                                                                            </div>
                                                                                        `;
            }

            // Initial render (first 4)
            for (let i = 0; i < visibleCount; i++) {
                container.innerHTML += topperCard(toppers[i]);
            }
            currentIndex = visibleCount;

            function slideNext() {
                const firstCard = container.firstElementChild;
                firstCard.classList.add("slide-left");

                setTimeout(() => {
                    container.removeChild(firstCard);

                    container.insertAdjacentHTML(
                        "beforeend",
                        topperCard(toppers[currentIndex])
                    );

                    currentIndex = (currentIndex + 1) % toppers.length;
                }, 800);
            }

            document.getElementById("nextTopper").onclick = slideNext;

            document.getElementById("prevTopper").onclick = () => {
                // optional (can be skipped)
            };

            setInterval(slideNext, 4500);
        });
    </script>

@endpush